fn report_head_reached_left(head: &HigherState) {
    use std::io::Write;
    print!("{} ", match head {
        HigherState::LeftA => "A",
        HigherState::LeftB => "B",
        HigherState::LeftC => "C",
        HigherState::LeftE => "E",
        HigherState::LeftF => "F",
        _ => unreachable!(),
    });
    std::io::stdout().flush().expect("could not flush stdout");
}

impl BlockSimulator {
    pub fn new() -> Self {
        use BlockSymbol::*;
        use RunSymbolType::*;
        Self {
            left_tape: vec![L],
            right_tape: vec![R, S, I],
            state: HigherState::Right,
            base_steps: 10,
            self_steps: 0
        }
    }

    pub fn step(&mut self) -> Result<(), SimError> {
        if matches!(self.left_tape.as_slice(), [BlockSymbol::L]) && self.state != HigherState::Right {
            if self.state == HigherState::LeftA {
                println!();
            }
            report_head_reached_left(&self.state);
        }

        let new_base_steps = self.basic_step()?;
        self.base_steps = self.base_steps.checked_add(new_base_steps.into()).unwrap();
        self.self_steps += 1;
        Ok(())
    }
}

fn main() {
    let mut sim = BlockSimulator::new();
    println!("{}", sim);
    for k in 1..=1000000 {
        let res = sim.step();
        // if k % 10000 == 0 {
        //     println!("{}", sim);
        // }
        if res.is_err() {
            println!("{:?}", res);
            break;
        }
    }
    println!();
    println!("{}", sim);
}